from lib import *
S = SS('w44')
steps = [
    step("本机与 SYN 洪水有关的参数:net.inet.tcp.syncookie = 1(允许 SYN cookie)、syncookie_hmac_sha256 = 0、drop_synfin = 1(丢弃同时带 SYN 和 FIN 的包)、kern.ipc.somaxconn = 128。netstat -s -p tcp 里相关的行(listen queue overflow、syncache entries aborted、SYN cookie sent、SYN cookie received)全是 0——但这台机器上这个命令的 TCP 部分所有计数都是 0(连“发出的包”都是 0),所以它们不能用来对账。", t=tl(S(1)), mark=lidx(S(1), 'net.inet.tcp.syncookie:', '0 SYN cookie sent', '0 SYN cookie received'), done=lidx(S(1), 'syncookie_hmac', 'drop_synfin', 'somaxconn', 'listen queue overflow', 'syncache entries aborted'), kv=KV([['syncookie', '1:允许启用'], ['drop_synfin', '1:丢弃 SYN+FIN'], ['somaxconn', '128'], ['netstat -s -p tcp', '所有计数都是 0,不可用']], ['syncookie'])),
    step("近似 SYN 洪水:没有原始套接字,无法伪造源地址,所以用 netlab 把第三个 ACK 拖慢(单向 400 ms),一口气发起 20000 个并发 connect(发完用了 6074 ms),抓服务端发出的 SYN-ACK。先用规模小一个数量级的并发做过同样的实验,所有连接都得到了选项完整的 SYN-ACK(MSS + SACK + 时间戳 + 窗口缩放),SYN cookie 计数不变。加到 20000 个后,抓到服务端发出的 SYN-ACK 131962 个(dummynet 重复抓到,按序号和确认号去重后 22787 个不同的连接/重传):127719 个选项完整,4243 个只有 MSS + SACK,没有时间戳和窗口缩放。按发出顺序,前 128 个 SYN-ACK 选项都是完整的,之后的 22659 个里有 3724 个是 MSS + SACK 的精简形态。这种“选项变少”与 SYN cookie 的特征一致(cookie 没有地方保存时间戳和窗口缩放),但本机 netstat -s -p tcp 的 TCP 计数全是 0(连“发出的包”都是 0),没法用来确认,所以只能说一致、不能确认就是 cookie。3 秒后客户端侧连上 527 个,服务端全连接队列 128/27/128:maxqlen 128 封顶,多余的握手完成后被 RST。", t=tl(S(2)), mark=lidx(S(2), 'SYN-ACK 选项组合', '按发出顺序', '3 秒后客户端侧'), done=lidx(S(2), '内发起了 20000', 'netstat -s -p tcp 里这段时间'), b=bars([['选项完整的 SYN-ACK', 127719, '127,719'], ['只有 MSS + SACK 的 SYN-ACK', 4243, '4,243'], ['最终连上的连接', 527, '527']], 127719, mark=[1], done=[0, 2]), kv=KV([['小规模并发', '全部 SYN-ACK 选项完整'], ['20000 个并发', '出现 4243 个只有 MSS + SACK 的 SYN-ACK'], ['netstat -s 的 TCP 计数', '全是 0:没法确认是不是 cookie'], ['全连接队列', '封顶 128']], ['netstat -s 的 TCP 计数'])),
    step("SYN cookie 的原理(计算演示,不是本机内核的真实格式):服务端不为半连接保存任何状态,把必要信息编进 SYN-ACK 的序号里。演示:客户端 192.0.2.7:40000 → 198.51.100.1:80,客户端 ISN 123456789,服务端把 SYN-ACK 的序号算成 999260433——高 5 位是时间戳低 5 位(7),接着 3 位是 MSS 索引(3,即 1460),低 24 位是对(四元组、客户端 ISN、时间戳)的 HMAC 截断。客户端回第三个 ACK,确认号 999260434,服务端用确认号 − 1 反推出时间戳 7 和 MSS 索引 3,重算哈希一致就接受连接;用伪造的 ACK(确认号 123456790)重算结果不一致,攻击者没有密钥就凑不出正确的哈希。代价是 SYN 里带来的窗口缩放、SACK、时间戳这些选项没处存,只能编进少量比特的 MSS,所以 cookie 只在队列快满时才启用。攻击面:SYN 洪水用伪造的源地址发大量 SYN,服务端为每个半连接保存状态直到超时,耗尽队列后正常客户端连不上;SYN cookie 让半连接不占内存。", t=tl(S(3)), mark=lidx(S(3), '客户端 192.0.2.7:40000', '客户端回第三个 ACK'), done=lidx(S(3), '代价', '攻击面'), kv=KV([['SYN-ACK 序号', '时间戳 5 位 + MSS 索引 3 位 + 哈希 24 位'], ['第三个 ACK', '确认号 − 1 反推并验证,服务端无状态'], ['代价', '窗口缩放 / SACK / 时间戳丢了'], ['演示', '计算,不是内核的真实格式']], ['演示'])),
]
A = mkartw('w44', 44, '网络协议,TCP,SYN Flood,SYN Cookie,syncache,netlab,真实验证,动画演示',
    '本机 syncookie = 1;用 netlab 拖慢握手并发起 20000 个并发连接,SYN-ACK 里出现 4243 个只有 MSS + SACK 的精简选项(与 cookie 的特征一致,但本机 netstat 的 TCP 计数全是 0,无法确认);SYN cookie 原理的计算演示。',
    '没有伪造源地址的能力,怎么研究 SYN Flood?这篇用 netlab 把握手拖慢,让两万个并发连接同时卡在半连接状态,看服务端的队列、SYN-ACK 的选项有没有变化,再用一个计算演示讲清 SYN cookie 怎么做到不保存状态。',
    [('20000 个并发', '用 netlab 拖慢握手后同时发起的连接数(小一个数量级时 SYN-ACK 选项全部完整)'), ('4243 个', '20000 个并发里出现的只有 MSS + SACK 的精简 SYN-ACK(没有时间戳和窗口缩放)'), ('24 位哈希', 'SYN cookie 演示里编进服务端序号的哈希位数(加 5 位时间戳、3 位 MSS 索引)')],
    [('SYN 洪水', '<p>伪造源地址发大量 SYN,服务端为每个半连接保存状态,队列耗尽后正常用户连不上。没有原始套接字,所以用延迟握手近似。</p>'),
     ('本机的反应', '<p>小一个数量级的并发时所有 SYN-ACK 都完整;20000 个并发时出现一批只有 MSS + SACK 的 SYN-ACK,全连接队列封顶 128,多出的连接握手完成后被 RST。</p>'),
     ('SYN cookie', '<p>把时间戳、MSS 索引和 HMAC 编进 SYN-ACK 序号,第三个 ACK 回来时反推验证,服务端不保存半连接状态;代价是丢掉窗口缩放等选项。</p>')],
    steps,
    [ENV_W + '。没有原始套接字权限,不能伪造源地址:这里的“洪水”只是同一个地址发出的大量并发 connect,握手被 netlab 拖慢到 800 ms;第二节先后运行过较小规模和 20000 个并发,取最后一次(20000 个)的数字;dummynet 会让同一个包被抓到多次,已按 (序号, 确认号) 去重;第三节是计算演示,不是 macOS 内核的 cookie 格式',
     '没有验证:SYN-ACK 选项变少是否确实是 SYN cookie(本机 netstat -s -p tcp 的 TCP 计数全是 0,不能对账);真实攻击下 syncache 的容量与淘汰策略;syncookie_hmac_sha256 开关的效果;syncache 与 so_incqlen 的关系;防火墙 / 负载均衡上的 SYN 代理'],
    'SYN Flood 与 SYN Cookie')
